style.css:
/* Retro Pac-Man dark blue theme */
body {
  position: relative;
  min-height: 100vh;
  margin: 0;
  background: none;
  overflow: hidden;
  font-family: 'Press Start 2P', monospace, sans-serif; /* optional arcade font */
}

/* Dark blue base */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;
  background: #0a0f40; /* arcade maze blue */
}

/* Pac-Man shapes (big circles with mouth cut) */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  pointer-events: none;

  /* Pac-Man created with conic-gradient */
  background-image: conic-gradient(
    #ffff00 0deg 320deg, /* yellow Pac-Man */
    transparent 320deg 360deg /* mouth slice */
  );

  background-size: 400px 400px; /* 10× bigger than before */
  background-repeat: repeat;
  animation: pacmanScroll 3s linear infinite; /* faster movement */
}

/* Animate Pac-Man grid */
@keyframes pacmanScroll {
  from { background-position: 0 0; }
  to   { background-position: 400px 400px; }
}

/* === TEXT COLORS === */
/* Default black text → white */
body, body * {
  color: #ffffff;
}

/* Links neon cyan for arcade vibe */
a {
  color: #00ffff !important;
}
